const D0=()=>dept===ALLCODE?ALL:dept.indexOf(",")>0?grpOf(dept):DEPTS.find(x=>x.code===dept);
/* 13 Oct 2026: a Site filter under the department filter. window.__dpSites
   holds the chosen site names (empty means all sites). Sites that are not
   under the chosen departments are dropped, and the cards are summed from
   the chosen sites, people counts capped as for the department. */
const D=()=>{
  const b=D0(), all=sitesFor(dept);
  window.__dpSiteList=all.map(s=>s.name);
  let f=window.__dpSites;
  if(f&&f.length){f=f.filter(n=>window.__dpSiteList.includes(n));window.__dpSites=f;}
  if(!f||!f.length)return b;
  const ss=all.filter(s=>f.includes(s.name)), sm=k=>ss.reduce((a,s)=>a+(+s[k]||0),0), u=Math.min(b.users,sm("users"));
  return Object.assign({},b,{sites:ss.length,docs:sm("docs"),rec:sm("rec"),phys:sm("phys"),due:sm("due"),
    visitors:sm("visitors"),views:sm("views"),users:u,gb:+sm("gb").toFixed(1),
    declaring:Math.min(b.declaring,sm("declaring"),u),creating:Math.min(b.creating,sm("creating"),u),
    idle180:Math.min(b.idle180,u),duephys:Math.min(b.duephys,sm("due")),
    recgb:+((+b.recgb||0)*(b.rec?sm("rec")/b.rec:0)).toFixed(1)});
};
